DRL: package Next_Possible_Queues_Rules;
//generated from Decision Table
import com.armedia.acm.plugins.businessprocess.model.NextPossibleQueuesModel;
import com.armedia.acm.plugins.casefile.model.CaseFile;
import gov.foia.model.FOIARequest;
import java.util.List;
import org.springframework.expression.EvaluationContext;
import org.springframework.expression.Expression;
import org.springframework.expression.ExpressionParser;
import org.springframework.expression.spel.standard.SpelExpressionParser;
import org.springframework.expression.spel.support.StandardEvaluationContext;
import java.util.Arrays;
function addQueues(String queues, NextPossibleQueuesModel model)
{
    String[] qa = queues.split(",");
    List<String> qs = Arrays.asList(qa);
    model.setNextPossibleQueues(qs);
}function Boolean evalSpring(String expression, Object obj)
{
    ExpressionParser ep = new SpelExpressionParser();
    Expression exp = ep.parseExpression(expression);
    EvaluationContext ec = new StandardEvaluationContext();

    Boolean evaluated = exp.getValue(ec, obj, Boolean.class);

    return evaluated;
}
// rule values at C21, header at C16
rule "Next Possible Queues Rules_21"
	salience 65535
	when
		$model: NextPossibleQueuesModel(((CaseFile)$model.getBusinessObject()).getQueue() != null && ((CaseFile)$model.getBusinessObject()).getQueue().getName().equals("Intake"))
	then
		addQueues("Fulfill,Hold,Approve", $model);
		$model.setDefaultNextQueue("Fulfill");
		$model.setDefaultReturnQueue(null);
		$model.setDefaultDenyQueue("Approve");
end

